'use cache'

import { cacheLife, cacheTag } from 'next/cache'
import { getPosts } from '@/lib/api'

export default async function Home() {
  cacheLife({
    stale: 3600,
    revalidate: 3600,
    expire: 3600,
  })
  cacheTag('posts')

  const posts = await getPosts()

  return (
    <main>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <strong>{post.title}</strong>
            <span> &mdash; by {post.author}</span>
          </li>
        ))}
      </ul>
    </main>
  )
}

